from typing import List
from tarea import Tarea

class GestorTareas:
    """Administra una colección de tareas."""
    def __init__(self):
        self.tareas: List[Tarea] = []

    def agregar_tarea(self, tarea: Tarea) -> None:
        self.tareas.append(tarea)

    def filtrar_por_prioridad(self, prioridad: str) -> List[Tarea]:
        return [t for t in self.tareas if t.prioridad == prioridad.strip().lower()]

    def completar_tarea(self, titulo: str) -> bool:
        for t in self.tareas:
            if t.titulo.strip().lower() == titulo.strip().lower():
                t.completada = True
                return True
        return False

