from typing import Dict
from cuenta import CuentaBancaria, SaldoInsuficienteError

class ProcesadorBanco:
    def __init__(self):
        self.cuentas: Dict[str, CuentaBancaria] = {}

    def registrar_cuenta(self, cuenta: CuentaBancaria) -> None:
        self.cuentas[cuenta.numero] = cuenta

    def transferir(self, origen: str, destino: str, monto: float) -> bool:
        if origen not in self.cuentas or destino not in self.cuentas:
            return False
        c_origen = self.cuentas[origen]
        c_destino = self.cuentas[destino]
        try:
            c_origen.retirar(monto)
            c_destino.depositar(monto)
            return True
        except SaldoInsuficienteError:
            return False

