import heapq
from typing import List, Optional
from paquete import Paquete

class EnrutadorQoS:
    def __init__(self, capacidad_maxima: int = 5):
        self.capacidad = capacidad_maxima
        self.cola = []
        self.descartados = 0
        self._contador = 0

    def recibir_paquete(self, p: Paquete) -> bool:
        if len(self.cola) >= self.capacidad:
            self.descartados += 1
            return False
        heapq.heappush(self.cola, (-p.prioridad, self._contador, p))
        self._contador += 1
        return True

    def despachar(self) -> Optional[Paquete]:
        if not self.cola:
            return None
        return heapq.heappop(self.cola)[2]

