from typing import List
from libro import Libro

class Biblioteca:
    def __init__(self, nombre: str):
        self.nombre = nombre
        self.catalogo: List[Libro] = []

    def agregar_libro(self, libro: Libro):
        self.catalogo.append(libro)

    def buscar_por_autor(self, autor: str) -> List[Libro]:
        return [l for l in self.catalogo if autor.lower() in l.autor.lower()]

    def prestar_libro(self, isbn: str) -> bool:
        for l in self.catalogo:
            if l.isbn == isbn and not l.prestado:
                l.prestado = True
                return True
        return False

