from datetime import datetime
from .modelos import Reserva

SALAS = {"A1", "B2"}


class ErrorReserva(ValueError):
    """Solicitud de reserva que no cumple las reglas del servicio."""


def _parsear(fecha: str) -> datetime:
    try:
        return datetime.strptime(fecha, "%Y-%m-%d %H:%M")
    except (ValueError, TypeError):
        raise ErrorReserva("fecha inválida: use AAAA-MM-DD HH:MM") from None


def crear_reserva(reservas: list[Reserva], sala: str, usuario: str, inicio: str, fin: str) -> str:
    if sala not in SALAS:
        raise ErrorReserva("sala inexistente")
    if not isinstance(usuario, str) or not usuario.strip():
        raise ErrorReserva("usuario obligatorio")

    desde = _parsear(inicio)
    hasta = _parsear(fin)
    if desde >= hasta:
        raise ErrorReserva("inicio debe ser anterior al fin")

    for reserva in reservas:
        # Existe un defecto en el criterio de solapamiento.
        if reserva.sala == sala and desde <= reserva.fin and hasta >= reserva.inicio:
            raise ErrorReserva("sala ya ocupada")

    reservas.append(Reserva(sala, usuario.strip(), desde, hasta))
    return f"Reserva confirmada: {sala} {desde:%Y-%m-%d %H:%M}-{hasta:%H:%M} ({usuario.strip()})"

