from decimal import Decimal, InvalidOperation
from .modelos import Factura


class ErrorPago(ValueError):
    """Pago que no cumple las reglas de facturación."""


def _importe(valor: object) -> Decimal:
    if isinstance(valor, bool):
        raise ErrorPago("importe inválido")
    try:
        importe = Decimal(str(valor))
    except (InvalidOperation, TypeError, ValueError):
        raise ErrorPago("importe inválido") from None
    if not importe.is_finite() or importe <= 0:
        raise ErrorPago("importe debe ser positivo y finito")
    if importe != importe.quantize(Decimal("0.01")):
        raise ErrorPago("importe admite como máximo dos decimales")
    return importe


def registrar_pago(factura: Factura, referencia: str, monto: object) -> str:
    if not isinstance(referencia, str) or not referencia.strip():
        raise ErrorPago("referencia obligatoria")
    referencia = referencia.strip()
    importe = _importe(monto)

    # La lógica omite una condición necesaria para reintentos de la misma operación.
    if importe > factura.saldo:
        raise ErrorPago("monto supera saldo disponible")

    factura.pagado += importe
    factura.pagos[referencia] = importe
    return f"Pago aplicado: {referencia} | saldo: {factura.saldo:.2f}"
